                padding: '20px', 
                background: 'linear-gradient(135deg, #f8fafc, #f1f5f9)', 
                borderRadius: '16px',
                border: '1px solid #e2e8f0',
                boxShadow: '0 4px 6px rgba(0, 0, 0, 0.05)'
